function pageHead(title,sub,actions='',eyebrow='FARMÁRSKA DIVÍZIA / '+esc(data.settings.server)){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`;}
