function daySlotsMarkup(date){
  const dayStart=Date.parse(date+'T00:00:00Z'),dayEnd=dayStart+86400000,events=data.jobs.filter(j=>j.status!=='cancelled'&&Date.parse(j.date+'T'+j.time+':00Z')<dayEnd&&Date.parse(j.date+'T'+j.time+':00Z')+scheduleSeconds(j)*1000>dayStart);
  return `<div class="day-slots" data-day-slots="${date}">${timeSlots.map((time,i)=>{const start=dayStart+i*1200000,end=start+1200000,list=events.filter(j=>{const t=Date.parse(j.date+'T'+j.time+':00Z');return t<end&&t+scheduleSeconds(j)*1000>start;});return `<div class="day-slot ${list.length?'has-booking':''}" data-time="${time}"><span class="slot-time">${time}</span><div class="slot-content">${list.map(j=>{const t=Date.parse(j.date+'T'+j.time+':00Z');return `<button class="slot-booking ${j.status}" data-action="calendar-detail" data-id="${j.id}" title="${esc(workText(j))} · rezervácia ${durationText(scheduleSeconds(j))}"><b>${t>=start?j.time:'Pokračuje'} · Farma #${esc(j.farm)}</b><small>${esc(workText(j))}</small></button>`;}).join('')||'<span class="slot-free">Voľný termín</span>'}</div>${allowed('jobs')?`<button class="slot-add icon-button" data-action="slot-job" data-date="${date}" data-time="${time}" aria-label="Pridať zákazku ${shortDate(date)} o ${time}">${icon('plus',14)}</button>`:''}</div>`;}).join('')}</div>`;
}
function scrollDaySlots(){setTimeout(()=>$$('[data-day-slots]').forEach(container=>{const date=container.dataset.daySlots,first=data.jobs.filter(j=>j.date===date&&j.status!=='cancelled').sort((a,b)=>a.time.localeCompare(b.time))[0],time=first?timeSlots[Math.floor((+first.time.slice(0,2)*60+ +first.time.slice(3))/20)]:'09:00',row=$(`[data-time="${time}"]`,container);if(row)container.scrollTop=Math.max(0,row.offsetTop-30);}),20);}
function openDaySlots(date){if(!gate('calendar'))return;modal(esc(formatDate(date,{weekday:'long',day:'numeric',month:'long'})),'Denný kalendár · termíny každých 20 minút',`<p class="day-slots-hint">${allowed('jobs')?'Plusom pri čase vytvoríš zákazku. Súbežné práce sú možné s inou partiou.':'Kliknutím na naplánovanú prácu zobrazíš podrobnosti.'}</p>${daySlotsMarkup(date)}`,'',570);scrollDaySlots();}
function dayDetail(j){return `<div class="day-detail">${badge(j.status)}<h4>${j.time} · Farma #${esc(j.farm)}</h4><p>${esc(workText(j))} · ${j.fields} políčok<br>${esc(j.floor)} · ${timerReadout(j)} · ${j.crew.length} osôb</p><button class="btn btn-text" style="margin-top:12px" data-action="calendar-detail" data-id="${j.id}">Zobraziť plán ${icon('arrow',13)}</button></div>`;}
function teamPage(){
  return pageHead('Silná partia. Férové pravidlá.','Ľudia, na ktorých stojí každá úspešne dokončená farma.',isLeader()?`<button class="btn btn-primary" data-action="new-user">${icon('plus')}Pridať člena</button>`:'')+`<div class="team-grid">${data.users.map(u=>`<article class="card team-card"><div class="team-card-top">${avatar(u)}<span class="badge ${u.role==='leader'?'badge-completed':'badge-planned'}">${roleName(u.role)}</span></div><h3>${esc(u.name)}</h3><p class="role">${u.active===false?'Prístup zablokovaný':u.id===session?'Tvoj pracovný profil':'Člen farmárskej partie'}</p><div class="team-stats"><span><b>${data.jobs.filter(j=>j.status==='completed'&&j.crew.includes(u.id)).length}</b>dokončených zákaziek</span><span><b>${money(earned(u.id))}</b>celkovo zarobené</span></div><div class="progress"><i style="width:${earned(u.id)?Math.min(100,paid(u.id)/earned(u.id)*100):0}%"></i></div><div class="money-status"><span>Vyplatené ${money(paid(u.id))}</span><span>${earned(u.id)?Math.round(paid(u.id)/earned(u.id)*100):0} %</span></div>${isLeader()?`<button class="btn btn-secondary" style="margin-top:20px" data-action="edit-user" data-id="${u.id}">${icon('edit',14)}Upraviť člena</button>`:''}</article>`).join('')}</div><section class="card table-card role-card"><div class="card-header"><div><h2>Oprávnenia podľa roly</h2><p class="sub">${isLeader()?'Uprav, čo majú členovia tímu k dispozícii. Zmeny sa ukladajú hneď.':'Prehľad prístupov v rámci tímu.'}</p></div>${icon('shield',22)}</div><div class="table-wrap"><table class="data-table permissions"><thead><tr><th>ČASŤ APLIKÁCIE</th><th>LEADER</th><th>ZAMESTNANEC</th></tr></thead><tbody>${Object.entries(routes).map(([r,[n]])=>`<tr><td>${n}${r==='payouts'?'<small class="muted">Zamestnanec vidí iba vlastné odmeny a výplaty.</small>':''}</td><td style="color:var(--accent)">${icon('check',15)}</td><td><input type="checkbox" data-permission="${r}" ${data.permissions.employee.includes(r)?'checked':''} ${!isLeader()?'disabled':''} aria-label="Povoliť zamestnancom: ${n}"></td></tr>`).join('')}</tbody></table></div></section><div class="help-box" style="margin-top:20px">${cloud?'<b>Prístup vynucuje databáza.</b> Zmena roly alebo zablokovanie člena platí aj pre už prihlásené zariadenia. Povolenie Prehľad, Zákazky, Kalkulačka alebo Štatistiky sprístupní obchodné údaje vrátane cien. Iba leader mení členov, nastavenia a výplaty.':'<b>Ukážkové roly:</b> ide o prepínanie rozhraní. Demo dáta sú uložené v tomto prehliadači.'}</div>`;
}
function payoutsPage(){
  const users=isLeader()?data.users:[user()],totalEarned=users.reduce((a,u)=>a+earned(u.id),0),totalPaid=users.reduce((a,u)=>a+paid(u.id),0),payments=data.payments.filter(p=>users.some(u=>u.id===p.uid)&&(payFilter==='all'||p.uid===payFilter)).sort((a,b)=>b.date.localeCompare(a.date)),personalJobs=data.jobs.filter(j=>j.status==='completed'&&j.crew.includes(session)).sort((a,b)=>b.date.localeCompare(a.date));
  return pageHead(isLeader()?'Dobrá práca si zaslúži odmenu.':'Tvoja práca. Tvoj zárobok.',isLeader()?'Presný prehľad odpracovaných zákaziek, odmien a odoslaných výplat.':'Vždy vieš, koľko si zarobil a kedy prišla tvoja výplata.',isLeader()?`<button class="btn btn-primary" data-action="new-payment">${icon('plus')}Zapísať výplatu</button>`:'')+`<div class="payout-grid"><div class="card payout-stat"><p>${isLeader()?'Tím celkovo zarobil':'Celkovo si zarobil'}</p><strong>${money(totalEarned)}</strong><small>Podiel z dokončených zákaziek</small></div><div class="card payout-stat"><p>Už vyplatené</p><strong>${money(totalPaid)}</strong><small>${payments.length} zaznamenaných výplat vo výbere</small></div><div class="card payout-stat accent"><p>Čaká na vyplatenie</p><strong>${money(totalEarned-totalPaid)}</strong><small>${isLeader()?'Zostatok na odmeny pre partiu':'Tvoj zostávajúci nárok na odmenu'}</small></div></div>${isLeader()?`<section class="card table-card" style="margin-bottom:23px"><div class="card-header"><h2>Zostatky členov tímu</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ČLEN TÍMU</th><th>ZAROBENÉ</th><th>VYPLATENÉ</th><th>ZOSTÁVA</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><span class="customer">${avatar(u)}${esc(u.name)}</span></td><td>${money(earned(u.id))}</td><td>${money(paid(u.id))}</td><td><b>${money(debt(u.id))}</b></td><td><button class="btn btn-text" data-action="pay-user" data-id="${u.id}" ${debt(u.id)<1?'disabled':''}>Zapísať výplatu ${icon('arrow',12)}</button></td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="card table-card"><div class="card-header"><div><h2>História výplat</h2><p class="sub">Záznamy odoslaných odmien v hernej mene</p></div>${isLeader()?`<select class="select-compact" id="pay-filter" aria-label="Filter výplat podľa člena"><option value="all">Celý tím</option>${users.map(u=>`<option value="${u.id}" ${payFilter===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>DÁTUM</th>${isLeader()?'<th>PRÍJEMCA</th>':''}<th>SUMA</th><th>POZNÁMKA</th><th>STAV</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${shortDate(p.date)}</td>${isLeader()?`<td><span class="customer">${avatar(data.users.find(u=>u.id===p.uid))}${esc(data.users.find(u=>u.id===p.uid)?.name)}</span></td>`:''}<td><b>${money(p.amount)}</b></td><td>${esc(p.note||'Priebežná výplata')}</td><td><span class="badge badge-completed">Zaznamenaná</span></td></tr>`).join('')||`<tr><td colspan="5"><div class="empty">Zatiaľ žiadne výplaty.</div></td></tr>`}</tbody></table></div><div class="table-footer"><span>Výplaty slúžia na evidenciu. Aplikácia neposiela herné peniaze.</span><span>${payments.length} záznamov</span></div></section>${!isLeader()?`<section class="card table-card" style="margin-top:23px"><div class="card-header"><div><h2>Za čo si zarobil</h2><p class="sub">Podiel z každej dokončenej zákazky rozdelený medzi pracovníkov</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>DÁTUM</th><th>FARMA</th><th>PRÁCA</th><th>TVOJ PODIEL</th><th>TVOJA ODMENA</th></tr></thead><tbody>${personalJobs.map(j=>`<tr><td>${shortDate(j.date)}</td><td>#${esc(j.farm)} / ${esc(j.floor)}</td><td>${esc(workText(j))}</td><td>${cloud&&Object.hasOwn(j,'myReward')?'—':pct(workerPercent(j,session))+' %'}</td><td><b>${money(workerReward(j,session))}</b></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Odmeny pribudnú po dokončení zákazky.</div></td></tr>'}</tbody></table></div></section>`:''}`;
}
function reportsPage(){const done=data.jobs.filter(j=>j.status==='completed'),sum=done.reduce((a,j)=>a+j.price,0),fields=done.reduce((a,j)=>a+j.fields,0),hours=done.reduce((a,j)=>a+jobSeconds(j)*j.crew.length/3600,0),team=done.reduce((a,j)=>a+j.price*teamPercent(j)/100,0);return pageHead('Rast, ktorý vidno.','Vaša práca v číslach. Každá dokončená farma sa počíta.',exportBtn())+`<div class="kpi-grid">${metric('Celkové tržby',money(sum),'Zo všetkých dokončených zákaziek','chart')}${metric('Spracované políčka',number(fields),'Naprieč všetkými typmi práce','leaf')}${metric('Odpracované osobohodiny',hours.toLocaleString('sk-SK',{maximumFractionDigits:1}),'Súčet času všetkých pracovníkov','clock')}${metric('Zostáva pre firmu',money(sum-team),'Tržby po odmenách pre pracovníkov','wallet')}</div>${chartCard()}<div class="report-work">${workNames.map(w=>{const jobs=done.filter(j=>jobWorks(j).includes(w)),value=jobs.reduce((a,j)=>a+j.price/jobWorks(j).length,0);return `<div class="card"><div class="eyebrow">${esc(w)}</div><strong>${money(value)}</strong><small>${jobs.length} zákaziek · podiel na tržbách</small><div class="bar-track"><i style="width:${sum?value/sum*100:0}%"></i></div></div>`;}).join('')}</div><div class="help-box">Štatistiky zahŕňajú iba dokončené zákazky. Pri viacerých prácach je cena pre tieto štatistiky rozdelená rovnomerne. Odmeny používajú individuálne podiely uložené pri konkrétnej zákazke. Plánované a zrušené práce nezvyšujú zárobok.</div>`;}
function settingsPage(){if(cloud)return cloudSettingsPage();return pageHead('Nastavené pre vašu partiu.','Vlastný názov, sadzby aj pravidlá odmeňovania.')+`<div class="settings-grid"><section class="card padded settings-card"><h2>Pracovný priestor</h2><p>Základné údaje zobrazené vo vašom paneli.</p><form id="workspace-form"><div class="form-grid"><div class="field wide"><label for="business-name">Názov partie</label><input id="business-name" name="name" value="${esc(data.settings.name)}" maxlength="40" required></div><div class="field"><label for="server-name">Herný server</label><input id="server-name" name="server" value="${esc(data.settings.server)}" maxlength="30" required></div><div class="field"><label for="currency">Označenie hernej meny</label><input id="currency" name="currency" value="${esc(data.settings.currency)}" maxlength="8" required></div></div><div class="form-footer"><button class="btn btn-primary" type="submit">${icon('check')}Uložiť údaje</button></div></form></section><section class="card padded settings-card"><h2>Cenník a rozdelenie odmien</h2><p>Základné sadzby pre kalkulačku a nové zákazky.</p><form id="rates-form"><div class="form-grid"><div class="field"><label for="field-rate">Základ za políčko (${esc(data.settings.currency)})</label><input id="field-rate" name="fieldRate" type="number" min="1" max="1000000" value="${data.settings.fieldRate}" required></div><div class="field"><label for="hour-rate">Osobohodina (${esc(data.settings.currency)})</label><input id="hour-rate" name="hourRate" type="number" min="1" max="1000000" value="${data.settings.hourRate}" required></div><div class="field wide"><label for="team-share">Predvolený rozpočet pre tím (%)</label><input id="team-share" name="share" type="number" min="0" max="100" value="${data.settings.share}" required><small>Použije sa pri tlačidle „Rozdeliť rovnomerne“. V zákazke môžeš každému nastaviť vlastné percento. Uložené zákazky sa nemenia.</small></div></div><div class="form-footer"><button class="btn btn-primary" type="submit">${icon('check')}Uložiť sadzby</button></div></form></section><section class="card padded settings-card"><h2>Dáta pod kontrolou</h2><p>HTML verzia ukladá zmeny v tomto prehliadači. Export si odlož ako zálohu. Na inom zariadení sa dáta automaticky nezobrazia.</p><div class="list-row"><div><b>Kompletná záloha</b><p>Zákazky, členovia, sadzby a výplaty v JSON.</p></div><button class="btn btn-secondary" data-action="backup">${icon('download')}Stiahnuť</button></div><div class="list-row"><div><b>Zákazky do tabuľky</b><p>CSV s údajmi pre Excel alebo Google Sheets.</p></div><button class="btn btn-secondary" data-action="export">${icon('download')}CSV</button></div><div class="list-row"><div><b>Začať s čistým panelom</b><p>Odstráni ukážkové zákazky a výplaty.</p></div><button class="btn btn-danger" data-action="clear-demo">Vymazať dáta</button></div></section><section class="card padded settings-card"><h2>O tejto verzii</h2><p>FarmCrew · HTML / CSS / JavaScript</p><div class="help-box"><b>Interaktívny prototyp pre SeeRPG.</b><br>Prepínanie profilov predvádza zamestnanecké roly. Táto verzia neoveruje heslá a neposkytuje bezpečné viacpoužívateľské prihlásenie. Pred spoločným ostrým používaním treba pripojiť server, databázu a prihlasovanie s kontrolou oprávnení.</div><div class="step-list"><p><b>Zapisujte zákazky</b> a priraďte im členov.</p><p><b>Po dokončení práce</b> sa vypočíta ich odmena.</p><p><b>Zaznamenajte výplatu</b> a tím uvidí svoj zostatok.</p></div></section></div>`;}
function profilePage(){return pageHead('Tvoj pracovný profil.','Tvoje miesto vo farmárskej partii.')+`<section class="card padded"><div class="personal-banner"><div><h2>${esc(user().name)}</h2><p>${roleName(user().role)} · ${esc(data.settings.name)}</p></div>${icon('leaf',60)}</div><button class="btn btn-primary" data-action="profile">${cloud?'Spravovať prihlásenie':'Zmeniť demo profil'}</button></section>`;}
function renderLogin(){if(cloud){renderCloudLogin();return;}$('#app').innerHTML=`<div class="login"><div class="login-theme">${themeButton()}</div><section class="login-visual"><a class="brand" href="#">${brand()}</a><div><div class="eyebrow">TVOJA PARTIA. TVOJ PRIESTOR.</div><h1>Veľké výsledky.<br>Jedna skvelá<br>partia.</h1><p>Od prvého políčka po férovú výplatu. Všetko, čo vaša farmárska partia potrebuje.</p></div><small style="color:#8b9c7b;z-index:1">Vytvorené pre komunitu SeeRPG.</small>${art()}</section><section class="login-form"><div class="brand" style="display:flex">${brand()}</div><span class="demo-pill">INTERAKTÍVNE HTML DEMO</span><h2>Vitaj vo FarmCrew.</h2><p>Vyber si pracovný profil a pozri sa, ako panel funguje z pohľadu leadera alebo zamestnanca.</p><div class="profile-options">${profileOptions()}</div><div class="help-box" style="margin-top:25px">Demo profily nevyžadujú heslo. Dáta sú uložené iba v tomto prehliadači. Skutočné prihlásenie a zdieľanie dát vyžadujú serverové pripojenie.</div></section></div>`;}
function profileOptions(){return data.users.map(u=>`<button class="profile-option" data-login="${u.id}">${avatar(u)}<span><b>${esc(u.name)}</b><small>${roleName(u.role)}${u.id===session?' · aktívny profil':''}</small></span>${icon('arrow',17)}</button>`).join('');}
let returnFocus=null;
function modal(title,sub,body,foot='',width=660){returnFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" style="width:${width}px"><header class="modal-header"><div><h2 id="modal-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Zavrieť okno">${icon('close')}</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-footer">${foot}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type=checkbox]),.modal select,.modal button')?.focus(),20);}
function closeModal(){$('#overlay-root').innerHTML='';document.body.style.overflow='';returnFocus?.focus?.();}
function formError(msg){const el=$('#form-error');if(el){el.className='error';el.textContent=msg;el.scrollIntoView({block:'nearest'});}else toast(msg,true);}
function jobForm(j=null,preset={}){
  if(!gate('jobs'))return;
  const obj=j||{first:'',last:'',farm:'1',floor:'1',fields:80,works:[...workNames],crew:[session],durationSeconds:0,estimatedDurationSeconds:0,date:today,time:'15:00',price:'',status:'planned',note:'',...preset},shares=j?Object.fromEntries(obj.crew.map(id=>[id,workerPercent(obj,id)])):equalShares(obj.crew,data.settings.share);
  const legacy=j&&(!farmNumbers.includes(String(j.farm))||!fieldSizes.includes(j.fields)||!timeSlots.includes(j.time)||jobWorks(j).some(w=>!workNames.includes(w)));
  modal(j?'Upraviť zákazku':'Nová zákazka',j?esc(j.id):'Priprav partiu na ďalšiu dobrú úrodu.',`<form id="job-form" data-id="${j?.id||''}" data-custom-shares="${j?'yes':'no'}"><div id="form-error" class="hidden"></div>${legacy?`<div class="help-box legacy-note"><b>Starší záznam zostal zachovaný.</b> Pôvodne farma #${esc(j.farm)}, ${j.fields} políčok, ${esc(workText(j))}, termín ${j.time}. Pri úprave vyber platné hodnoty nového formulára.</div>`:''}<div class="form-grid"><div class="field"><label for="j-first">Meno zákazníka *</label><input id="j-first" name="first" value="${esc(obj.first)}" maxlength="50" required></div><div class="field"><label for="j-last">Priezvisko zákazníka *</label><input id="j-last" name="last" value="${esc(obj.last)}" maxlength="60" required></div><div class="field"><label for="j-farm">Číslo farmy *</label><select id="j-farm" name="farm" required>${farmNumbers.includes(String(obj.farm))?'':'<option value="" selected disabled>Vyber farmu 1–7</option>'}${optionList(farmNumbers,obj.farm,'Farma #')}</select></div><div class="field"><label for="j-floor">Poschodie *</label><input id="j-floor" name="floor" type="text" value="${esc(obj.floor)}" maxlength="30" placeholder="Napr. 2 alebo prízemie" required></div><div class="field"><label for="j-fields">Počet políčok *</label><select id="j-fields" name="fields" required>${fieldSizes.includes(obj.fields)?'':'<option value="" selected disabled>Vyber počet políčok</option>'}${optionList(fieldSizes,obj.fields)}</select></div><div class="field"><label for="j-status">Stav zákazky</label>${['active','completed'].includes(obj.status)?`<div class="status-readonly">${badge(obj.status)}</div><input type="hidden" name="status" value="${obj.status}"><small>Stav meníš tlačidlami Začať a Dokončiť.</small>`:`<select id="j-status" name="status">${['planned','cancelled'].map(v=>`<option value="${v}" ${obj.status===v?'selected':''}>${statusNames[v]}</option>`).join('')}</select>`}</div><div class="field wide"><label>Práce na farme *</label>${workChoices('j',jobWorks(obj))}<small>Môžeš vybrať viacero prác naraz.</small></div><div class="field"><label for="j-date">Dátum *</label><input id="j-date" type="date" name="date" value="${obj.date}" required></div><div class="field"><label for="j-time">Čas začiatku *</label><select id="j-time" name="time" required>${timeOptions(obj.time)}</select><small>Termíny každých 20 minút.</small></div><div class="field wide">${obj.status==='completed'&&!Number.isFinite(obj.startedAt)?`<label>Uložený čas dokončenej práce *</label>${durationFields('j',storedJobSeconds(obj))}<small>Pôvodný záznam bez automatického merania.</small>`:`${timerPanel(obj)}${obj.status!=='completed'?`<details class="estimate-details" ${obj.estimatedDurationSeconds?'open':''}><summary>Odhad trvania pre kalendár (nepovinné)</summary><p>Slúži iba na rezerváciu termínu. Skutočný čas sa odmeria automaticky. Bez odhadu rezervujeme 20 minút.</p>${durationFields('j-estimate',obj.estimatedDurationSeconds||0,false)}</details>`:''}`}</div><div class="field wide"><label for="j-price">Dohodnutá cena (${esc(data.settings.currency)}) *</label><input id="j-price" type="number" name="price" min="1" max="1000000000" value="${obj.price}" required></div><div class="field wide"><div class="crew-heading"><label>Pracovníci a individuálne podiely *</label><button type="button" class="btn btn-text" data-action="equal-shares">Rozdeliť rovnomerne</button></div><small>Každému nastav percento z celej ceny zákazky. Zvyšok zostáva firme.</small><div class="crew-share-list">${data.users.map(u=>{const checked=obj.crew.includes(u.id),value=Number((shares[u.id]??0).toFixed(6));return `<div class="crew-share-row"><label class="crew-person"><input type="checkbox" name="crew" value="${u.id}" ${checked?'checked':''}>${avatar(u)}<span>${esc(u.name)}</span></label><label class="share-control"><input name="share-${u.id}" data-worker-share="${u.id}" type="number" min="0" max="100" step="any" value="${value}" ${checked?'required':'disabled'} aria-label="Podiel z ceny pre ${esc(u.name)}"><span>%</span></label><span class="worker-share-amount" data-worker-amount="${u.id}">${checked?money((+obj.price||0)*value/100):'—'}</span></div>`;}).join('')}</div><div id="share-summary" class="share-summary" aria-live="polite"></div><small id="crew-count">Počet pracovníkov: ${obj.crew.length}</small></div><div class="field wide"><label for="j-note">Poznámka</label><textarea id="j-note" name="note" rows="2" maxlength="1500" placeholder="Dôležité informácie pre partiu…">${esc(obj.note)}</textarea></div></div></form>`,`<button class="btn btn-secondary" data-action="close-modal">Zrušiť</button><button class="btn btn-primary" form="job-form" type="submit">${icon('check')}Uložiť zákazku</button>`,720);
  updateShareSummary();
}
function splitFormShares(){const form=$('#job-form');if(!form)return;const crew=$$('[name="crew"]:checked',form).map(x=>x.value),shares=equalShares(crew,data.settings.share);$$('[data-worker-share]',form).forEach(input=>{input.value=shares[input.dataset.workerShare]??0;});form.dataset.customShares='no';updateShareSummary();}
function updateShareSummary(){const form=$('#job-form');if(!form)return;const crew=$$('[name="crew"]:checked',form).map(x=>x.value),price=+$('#j-price').value||0;let total=0;$$('[data-worker-share]',form).forEach(input=>{const selected=crew.includes(input.dataset.workerShare);input.disabled=!selected;input.required=selected;const share=selected?Number(input.value):0;total+=share;const out=$(`[data-worker-amount="${input.dataset.workerShare}"]`,form);if(out)out.innerHTML=selected&&Number.isFinite(share)?money(price*share/100):'—';});$('#crew-count').textContent='Počet pracovníkov: '+crew.length;const summary=$('#share-summary');summary.classList.toggle('over-limit',!Number.isFinite(total)||total>100+1e-9);summary.innerHTML=Number.isFinite(total)?`<span>Pre tím <b>${pct(total)} %</b> · ${money(price*total/100)}</span><span>Pre firmu <b>${pct(100-total)} %</b> · ${money(price*(100-total)/100)}</span>`:'Zadaj platné percentá.';}

function jobDetail(id,calendarOnly=false){
  const j=data.jobs.find(j=>j.id===id);if(!j)return;
  const full=allowed('jobs')&&!calendarOnly;
  if(!full&&!allowed('calendar'))return;
  const crew=j.crew.map(id=>data.users.find(u=>u.id===id));
  modal(full?'Detail zákazky':'Plán práce',`${esc(j.id)} · ${shortDate(j.date)} o ${j.time}`,`${full?`<div class="detail-price"><span>Dohodnutá cena<br><small>Podiel pre tím: ${pct(teamPercent(j))} %</small></span><strong>${money(j.price)}</strong></div>`:''}${timerPanel(j)}<dl class="detail-grid">${(full?[['Zákazník',esc(j.first+' '+j.last)]]:[]).concat([['Farma / poschodie',`#${esc(j.farm)} / ${esc(j.floor)}`],['Práca',esc(workText(j))],['Veľkosť farmy',j.fields+' políčok'],['Čas práce',timerReadout(j)],['Termín',shortDate(j.date)+' · '+j.time],['Stav',badge(j.status)],['Pracovníci',crew.map(u=>esc(u?.name)).join(', ')+' ('+crew.length+')']]).map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${full&&j.status==='active'?`<button class="btn btn-text timer-cancel" data-action="cancel-job" data-id="${j.id}">Zrušiť zákazku a zastaviť meranie</button>`:''}${j.note&&full?`<div class="detail-note"><b>Poznámka</b><br>${esc(j.note)}</div>`:''}${full?`<div class="detail-note"><b>Individuálne podiely z ceny</b>${j.crew.map(id=>`<div class="list-row"><span>${esc(data.users.find(u=>u.id===id)?.name)} · ${pct(workerPercent(j,id))} %</span><strong>${money(workerReward(j,id))}</strong></div>`).join('')}<div class="list-row"><span>Pre firmu · ${pct(100-teamPercent(j))} %</span><strong>${money(j.price*(100-teamPercent(j))/100)}</strong></div></div>`:''}`,`${full?`<button class="btn btn-danger left" data-action="delete-job" data-id="${j.id}">${icon('trash')}Odstrániť</button><button class="btn btn-secondary" data-action="edit-job" data-id="${j.id}">${icon('edit')}Upraviť</button>${hasRunningTimer(j)?`<button class="btn btn-primary" data-action="complete-job" data-id="${j.id}">${icon('check')}Dokončiť</button>`:['planned','active'].includes(j.status)?`<button class="btn btn-primary" data-action="start-job" data-id="${j.id}">${icon('clock')}Začať zákazku</button>`:''}`:`<button class="btn btn-secondary" data-action="close-modal">Zavrieť</button>`}`);
}
function applyJobChange(list){if(cloud)throw new Error('Use a database job command.');for(const u of data.users)if(paid(u.id)>earned(u.id,list)+.01){formError('Táto zmena by znížila zárobok člena '+u.name+' pod už vyplatenú sumu. Najprv vyriešte výplaty.');return false;}data.jobs=list;save();closeModal();render();return true;}
function employeeForm(u=null){if(cloud){cloudMemberForm(u);return;}if(!isLeader()||!gate('team'))return;modal(u?'Upraviť člena':'Nový člen partie','Demo pracovný profil bez hesla.',`<form id="user-form" data-id="${u?.id||''}"><div id="form-error" class="hidden"></div><div class="form-grid"><div class="field wide"><label for="u-name">Meno a priezvisko *</label><input id="u-name" name="name" value="${esc(u?.name||'')}" maxlength="80" required></div><div class="field wide"><label for="u-role">Pracovná rola</label><select id="u-role" name="role"><option value="employee" ${u?.role==='employee'?'selected':''}>Zamestnanec</option><option value="leader" ${u?.role==='leader'?'selected':''}>Leader tímu</option></select><small>Leader spravuje zákazky, ceny, členov aj výplaty.</small></div></div></form>`,`<button class="btn btn-secondary" data-action="close-modal">Zrušiť</button><button class="btn btn-primary" form="user-form" type="submit">Uložiť člena</button>`,480);}
function paymentForm(uid=''){
  if(!isLeader()||!gate('payouts'))return;const selected=uid||data.users.find(u=>debt(u.id)>0)?.id||data.users[0].id;
  modal('Zapísať odoslanú výplatu','Záznam vyplatených herných peňazí členovi partie.',`<form id="payment-form"><div id="form-error" class="hidden"></div><div class="form-grid"><div class="field wide"><label for="p-user">Príjemca</label><select id="p-user" name="uid">${data.users.map(u=>`<option value="${u.id}" ${selected===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select><small id="payment-balance">Čaká na vyplatenie: ${money(debt(selected))}</small></div><div class="field"><label for="p-amount">Vyplatená suma (${esc(data.settings.currency)}) *</label><input id="p-amount" name="amount" type="number" min="1" max="${Math.floor(debt(selected))}" value="${Math.floor(debt(selected))||''}" required></div><div class="field"><label for="p-date">Dátum odoslania *</label><input id="p-date" name="date" type="date" max="${today}" value="${today}" required></div><div class="field wide"><label for="p-note">Poznámka</label><textarea id="p-note" name="note" rows="2" maxlength="300" placeholder="Napr. výplata za tento týždeň"></textarea></div></div><div class="help-box" style="margin-top:20px">Zapíš iba sumu, ktorú si už poslal v hre. Táto akcia aktualizuje evidenciu a sama peniaze neposiela.</div></form>`,`<button class="btn btn-secondary" data-action="close-modal">Zrušiť</button><button class="btn btn-primary" form="payment-form" type="submit">${icon('check')}Zapísať výplatu</button>`,520);
}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJobs(){if(!allowed('jobs')&&!allowed('reports')&&!allowed('settings'))return;const cols=['ID','Meno','Priezvisko','Farma','Poschodie','Políčka','Práce','Počet pracovníkov','Pracovníci','Skutočný čas (HH:MM:SS)','Odhad pre kalendár','Spustené','Dokončené','Dátum','Začiatok','Cena ('+data.settings.currency+')','Stav','Podiel tímu (%)','Individuálne podiely','Poznámka'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=data.jobs.map(j=>[j.id,j.first,j.last,j.farm,j.floor,j.fields,workText(j),j.crew.length,j.crew.map(id=>data.users.find(u=>u.id===id)?.name).join(', '),j.status==='completed'||hasRunningTimer(j)||j.stoppedAt!=null?durationText(jobSeconds(j)):'',j.estimatedDurationSeconds?durationText(j.estimatedDurationSeconds):'',Number.isFinite(j.startedAt)?timerDate(j.startedAt):'',Number.isFinite(j.completedAt)?timerDate(j.completedAt):'',j.date,j.time,j.price,statusNames[j.status],teamPercent(j),j.crew.map(id=>(data.users.find(u=>u.id===id)?.name||id)+': '+pct(workerPercent(j,id))+' % ('+number(workerReward(j,id))+' '+data.settings.currency+')').join('; '),j.note]);download('\ufeff'+[cols,...rows].map(row=>row.map(cell).join(';')).join('\r\n'),`farmcrew-zakazky-${today}.csv`,'text/csv;charset=utf-8');toast('Export zákaziek je pripravený.');}
function helpModal(){if(cloud){modal('FarmCrew · spoločný panel','Jeden tím. Rovnaké údaje na každom zariadení.','<div class="help-box">Leader spravuje členov, zákazky a výplaty. Zamestnanec vidí časti povolené leaderom; výplaty má vlastné. Stopky meria databáza aj pri zatvorenej stránke. Výplaty evidujú peniaze odoslané v hre.</div>');return;}modal('Vitaj vo FarmCrew.','Jeden tím. Všetko na jednom mieste.',`<div class="help-box"><b>Interaktívna HTML ukážka</b><br>Zmeny sa ukladajú do tohto prehliadača. Demo roly a profily predvádzajú správanie panelu; nejde o bezpečné prihlásenie. Pre spoločné používanie partie treba server, databázu a kontrolu oprávnení na serveri.</div><div class="step-list"><p><b>Leader</b> zapisuje zákazky, plánuje termíny, naceňuje a eviduje výplaty.</p><p><b>Zamestnanec</b> predvolene vidí kalendár práce a svoje odmeny. Ďalšie časti povolíš v Tím a oprávnenia.</p><p><b>Kalkulačka</b> odhaduje cenu z podobných dokončených zákaziek, políčok a osobohodín. Voliteľne zohľadní predošlú cenu.</p><p><b>Stopky</b> spustíš tlačidlom „Začať zákazku“. „Dokončiť“ uloží skutočné trvanie aj po obnovení alebo zatvorení stránky.</p><p><b>Odmeny</b> pribúdajú po dokončení práce. Každý pracovník má vlastné percento z ceny zákazky. Súčet môže byť najviac 100 %; zvyšok zostáva firme.</p><p><b>Výplaty</b> sú záznamy peňazí už odoslaných v hre. Aplikácia sama peniaze neposiela.</p></div>`,`<button class="btn btn-primary" data-action="close-modal">Rozumiem ${icon('check')}</button>`,580);}

function cloudMessage(error){
  const messages={CONFLICT:'Zákazku medzitým zmenil iný člen. Obnov panel a skontroluj zmenu pred opätovným uložením.',MEMBERSHIP_REQUIRED:'Tento účet nemá aktívny prístup. Over svoj e-mail alebo požiadaj leadera o pridanie do partie.',AUTH_REQUIRED:'Prihlásenie vypršalo. Prihlás sa znova.',FORBIDDEN:'Na túto zmenu nemáš oprávnenie.',ALREADY_PAID:'Zmena by znížila zárobok pod už vyplatenú sumu.',WORKER_BUSY:'Člen partie už má spustenú inú zákazku.',BOOKING_CONFLICT:'Termín sa prekrýva s inou zákazkou tejto partie.',PAYMENT_EXCEEDS_BALANCE:'Výplata presahuje nevyplatený zárobok.',FUTURE_PAYMENT:'Výplata nemôže mať budúci dátum.',LAST_LEADER:'Partia musí mať aspoň jedného aktívneho leadera.',KEEP_OWN_ACCESS:'Vlastný e-mail ani aktívny prístup tu nemôžeš zrušiť.',INVALID_STATUS:'Stav zákazky sa zmenil. Obnov panel.',JOB_NOT_FOUND:'Zákazka už neexistuje.',INVALID_SHARES:'Skontroluj percentá pracovníkov. Súčet môže byť najviac 100 %.',INVALID_JOB:'Skontroluj údaje zákazky.',INVALID_MEMBER:'Skontroluj meno, e-mail a rolu člena.',INVALID_SETTINGS:'Skontroluj názov partie a hodnoty cenníka.',INVALID_PERMISSIONS:'Neplatné oprávnenia.'};
  const message=error?.message||'';
  if(messages[message])return messages[message];
  if(message.includes('Invalid login credentials'))return 'Nesprávny e-mail alebo heslo.';
  if(message.includes('Email not confirmed'))return 'Najprv potvrď svoj e-mail cez odkaz, ktorý ti prišiel.';
  if(error?.code==='23505')return 'Tento e-mail alebo člen už v partii existuje.';
  if(/rate|security purposes|too many/i.test(message))return 'Príliš veľa pokusov. Skús to o chvíľu.';
  return 'Spojenie alebo uloženie sa nepodarilo. Skontroluj pripojenie a obnov panel; pred opakovaním skontroluj, či sa zmena už uložila.';
}
function acceptCloud(snapshot){
  if(!snapshot||!Array.isArray(snapshot.jobs)||!Array.isArray(snapshot.users))throw new Error('INVALID_RESPONSE');
  data=snapshot;session=snapshot.memberId;serverOffset=snapshot.serverNow-Date.now();cloudError='';cloudLoading=false;
  if(!user())throw new Error('MEMBERSHIP_REQUIRED');
}
async function cloudWrite(action,payload){
  if(!cloud||cloudBusy||cloud.configurationError){formError('Počkaj na dokončenie pripojenia.');return false;}
  cloudBusy=true;document.body.classList.add('cloud-saving');
  try{const result=await cloud.command(action,payload);acceptCloud(result);closeModal();render();return result;}
  catch(error){cloudError=cloudMessage(error);formError(cloudError);return false;}
  finally{cloudBusy=false;document.body.classList.remove('cloud-saving');}
}
async function remoteLifecycle(action,id,message){if(!gate('jobs'))return false;const result=await cloudWrite(action,{id});if(!result)return false;if(action!=='job_cancel')jobDetail(id);toast(message);return true;}
async function refreshCloud(manual=false){
  if(cloudBusy||cloud.configurationError||(!manual&&($('#overlay-root').innerHTML||document.hidden)))return;
  cloudBusy=true;
  try{const result=await cloud.load();if(!result){session=null;data=emptyCloudData();}else acceptCloud(result);cloudLoading=false;render();if(manual)toast('Spoločný panel je obnovený.');}
  catch(error){cloudLoading=false;cloudError=cloudMessage(error);if(['MEMBERSHIP_REQUIRED','AUTH_REQUIRED'].includes(error?.message)){data=emptyCloudData();session=null;closeModal();render();}if(!session)renderCloudLogin();if(manual)toast(cloudError,true);}
  finally{cloudBusy=false;}
}
async function bootCloud(){
  if(cloud.configurationError){cloudLoading=false;cloudError=cloud.configurationError;renderCloudLogin();return;}
  renderCloudLogin();
  cloud.onAuthChange((event)=>{
    if(event==='PASSWORD_RECOVERY'){authMode='password';cloudLoading=false;closeModal();renderCloudLogin();}
    else if(event==='SIGNED_OUT'){data=emptyCloudData();session=null;cloudLoading=false;authMode='login';closeModal();renderCloudLogin();}
    else if(event==='SIGNED_IN'&&!cloudBusy&&!cloudLoading&&authMode!=='password')refreshCloud();
  });
  try{if(await cloud.session())await refreshCloud();else{cloudLoading=false;renderCloudLogin();}}
  catch(error){cloudLoading=false;cloudError=cloudMessage(error);renderCloudLogin();}
  window.setInterval?.(()=>{if(session)refreshCloud();},20000);
  window.addEventListener('focus',()=>{if(session)refreshCloud();});
}
async function cloudLogout(){
  if(cloudBusy)return;
  cloudBusy=true;
  try{await cloud.signOut();data=emptyCloudData();session=null;authMode='login';cloudError='';closeModal();renderCloudLogin();}
  catch(error){toast(cloudMessage(error),true);}
  finally{cloudBusy=false;}
}
function renderCloudLogin(){
  const register=authMode==='register',reset=authMode==='reset',password=authMode==='password';
  $('#app').innerHTML=`<div class="login"><div class="login-theme">${themeButton()}</div><section class="login-visual"><a class="brand" href="#">${brand()}</a><div><div class="eyebrow">TVOJA PARTIA. TVOJ PRIESTOR.</div><h1>Dobrá partia.<br>Spoločné<br>výsledky.</h1><p>Všetky zákazky, pracovné termíny a férové odmeny v jednom priestore pre celý tím.</p></div><small style="color:#8b9c7b;z-index:1">FarmCrew pre komunitu SeeRPG.</small>${art()}</section><section class="login-form"><div class="brand" style="display:flex">${brand()}</div><span class="demo-pill"><span class="live"></span>SPOLOČNÝ PANEL</span><h2>${cloudLoading?'Pripájame tvoju partiu…':register?'Pridaj sa k partii.':reset?'Obnov si heslo.':password?'Nastav nové heslo.':'Vitaj späť.'}</h2><p>${register?'Použi e-mail, pod ktorým ťa leader pridal do partie. Potom ho potvrď cez doručený odkaz.':reset?'Pošleme ti odkaz na nastavenie nového hesla.':'Prihlás sa do svojho pracovného priestoru.'}</p>${cloudError?`<div class="error" role="alert">${esc(cloudError)}</div>`:''}${cloudLoading?'<div class="help-box">Overujeme prihlásenie a aktuálne oprávnenia.</div>':cloud.configurationError?'<div class="help-box">Pracovný priestor čaká na dokončenie pripojenia.</div>':`<form id="cloud-auth-form"><div id="form-error" class="hidden"></div><div class="form-grid">${password?'':`<div class="field wide"><label for="auth-email">E-mail</label><input id="auth-email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="tvoj@email.sk"></div>`}${reset?'':`<div class="field wide"><label for="auth-password">${password?'Nové heslo':'Heslo'}</label><input id="auth-password" name="password" type="password" autocomplete="${register||password?'new-password':'current-password'}" minlength="${register||password?12:1}" maxlength="128" required>${register||password?'<small>Použi aspoň 12 znakov.</small>':''}</div>`}</div><button class="btn btn-primary cloud-auth-submit" type="submit">${register?'Vytvoriť účet':reset?'Poslať odkaz':password?'Uložiť nové heslo':'Prihlásiť sa'} ${icon('arrow',16)}</button></form><div class="cloud-auth-links">${authMode==='login'?'<button class="btn btn-text" data-action="auth-register">Som tu prvýkrát</button><button class="btn btn-text" data-action="auth-reset">Zabudnuté heslo</button>':'<button class="btn btn-text" data-action="auth-login">Späť na prihlásenie</button>'}</div><div class="help-box">Prístup získajú iba členovia pridaní leaderom. Každý používa vlastný účet.</div><button class="btn btn-text" data-action="logout">Odhlásiť uložený účet</button>`}</section></div>`;
}
async function submitCloudAuth(v){
  if(cloudBusy||cloud.configurationError)return;cloudBusy=true;document.body.classList.add('cloud-saving');
  try{
    if(authMode==='reset'){await cloud.reset(v.email);toast('Ak účet existuje, príde ti odkaz na obnovu hesla.');authMode='login';renderCloudLogin();}
    else if(authMode==='register'){const result=await cloud.signUp(v.email,v.password);if(result.session){acceptCloud(await cloud.load());land();render();}else{authMode='login';cloudError='';renderCloudLogin();toast('Skontroluj e-mail a potvrď vytvorenie účtu.');}}
    else{if(authMode==='password')await cloud.password(v.password);else await cloud.signIn(v.email,v.password);acceptCloud(await cloud.load());authMode='login';land();render();}
  }catch(error){formError(cloudMessage(error));}
  finally{cloudBusy=false;document.body.classList.remove('cloud-saving');}
}
function cloudProfile(){modal('Tvoj účet',esc(user().name)+' · '+roleName(user().role),`<div class="help-box">Prihlásenie je viazané na tvoj účet. Oprávnenia spravuje leader partie.</div><p class="text-muted" style="margin-top:16px">${esc(user().email||'Súkromný pracovný účet')}</p>`,`<button class="btn btn-secondary" data-action="close-modal">Zavrieť</button><button class="btn btn-primary" data-action="logout">${icon('logout')}Odhlásiť sa</button>`,480);}
function cloudMemberForm(u){
  if(!isLeader()||!gate('team'))return;
  modal(u?'Upraviť člena':'Pridať člena partie','Člen si vytvorí vlastný účet pod zadaným e-mailom.',`<form id="cloud-member-form" data-id="${esc(u?.id||'')}"><div id="form-error" class="hidden"></div><div class="form-grid"><div class="field wide"><label for="u-name">Meno a priezvisko</label><input id="u-name" name="name" value="${esc(u?.name||'')}" minlength="3" maxlength="80" required></div><div class="field wide"><label for="u-email">E-mail pre prihlásenie</label><input id="u-email" name="email" type="email" value="${esc(u?.email||'')}" maxlength="254" required ${u?.id===session?'readonly':''}></div><div class="field"><label for="u-role">Rola</label><select id="u-role" name="role"><option value="employee" ${u?.role==='employee'?'selected':''}>Zamestnanec</option><option value="leader" ${u?.role==='leader'?'selected':''}>Leader</option></select></div><div class="field"><label for="u-active">Prístup</label><select id="u-active" name="active"><option value="true" ${u?.active!==false?'selected':''}>Aktívny</option><option value="false" ${u?.active===false?'selected':''}>Zablokovaný</option></select></div></div><div class="help-box" style="margin-top:20px">Členovi pošli adresu panelu. Cez „Som tu prvýkrát“ si vytvorí účet. Heslo si volí sám. Zablokovaný člen sa nedostane k údajom ani s predchádzajúcim prihlásením.</div></form>`,`<button class="btn btn-secondary" data-action="close-modal">Zrušiť</button><button class="btn btn-primary" form="cloud-member-form" type="submit">Uložiť člena</button>`,520);
}
function localBackup(){try{const raw=localStorage.getItem(keys.data);if(!raw){toast('V tomto prehliadači nie je staršia lokálna záloha.');return;}download(raw,`farmcrew-lokalna-zaloha-${today}.json`,'application/json');toast('Pôvodná lokálna záloha je pripravená.');}catch{toast('Lokálnu zálohu sa nepodarilo prečítať.',true);}}
function cloudSettingsPage(){
  const s=data.settings;
  return pageHead('Nastavené pre vašu partiu.','Spoločné údaje, cenník a zálohy.',`<button class="btn btn-secondary" data-action="cloud-refresh">${icon('clock')}Obnoviť panel</button>`)+`<div class="settings-grid"><section class="card padded settings-card"><h2>Pracovný priestor</h2><form id="workspace-form"><fieldset class="cloud-fieldset" ${!isLeader()?'disabled':''}><div class="form-grid">${[['name','Názov partie',40],['server','Herný server',30],['currency','Herná mena',8]].map(([k,label,max])=>`<div class="field wide"><label for="cloud-${k}">${label}</label><input id="cloud-${k}" name="${k}" value="${esc(s[k])}" maxlength="${max}" required></div>`).join('')}</div><div class="form-footer"><button class="btn btn-primary" type="submit">Uložiť údaje</button></div></fieldset></form></section><section class="card padded settings-card"><h2>Cenník a odmeny</h2><form id="rates-form"><fieldset class="cloud-fieldset" ${!isLeader()?'disabled':''}><div class="form-grid">${[['fieldRate','Základ za políčko',1,1000000],['hourRate','Osobohodina',1,1000000],['share','Predvolený podiel tímu (%)',0,100]].map(([k,label,min,max])=>`<div class="field wide"><label for="cloud-${k}">${label}</label><input id="cloud-${k}" name="${k}" type="number" value="${s[k]}" min="${min}" max="${max}" step="any" required></div>`).join('')}</div><div class="form-footer"><button class="btn btn-primary" type="submit">Uložiť cenník</button></div></fieldset></form></section><section class="card padded settings-card"><h2>Dáta pod kontrolou</h2><p>Zmeny sa ukladajú pre celú partiu. Pri otvorenom paneli sa údaje obnovujú každých 20 sekúnd. Rozpracovaný formulár zostáva na mieste.</p>${isLeader()?'<button class="btn btn-secondary" data-action="backup">Stiahnuť spoločnú zálohu</button>':''}<div class="list-row"><div><b>Pôvodná lokálna verzia</b><p>Predchádzajúce údaje z tohto prehliadača zostali zachované.</p></div><button class="btn btn-secondary" data-action="local-backup">Stiahnuť</button></div></section><section class="card padded settings-card"><h2>Prihlásenie a prístup</h2><div class="help-box">Každý člen má vlastný účet. Leader spravuje e-maily, roly a blokovanie v časti Tím. Výplaty sú evidencia peňazí už odoslaných v hre.</div><button class="btn btn-secondary" style="margin-top:20px" data-action="profile">Môj účet</button></section></div>`;
}

document.addEventListener('click',async e=>{
  const login=e.target.closest('[data-login]');if(login){if(cloud)return;setSession(login.dataset.login);toast('Pracovný profil: '+user().name);return;}
  const nav=e.target.closest('[data-page]');if(nav){if(!gate(nav.dataset.page))return;page=nav.dataset.page;closeModal();render();if(page==='pricing')updateCalc();window.scrollTo(0,0);return;}
  const filter=e.target.closest('[data-filter]');if(filter){jobFilter=filter.dataset.filter;render();return;}
  const el=e.target.closest('[data-action]');
  if(el){const action=el.dataset.action,id=el.dataset.id,j=data.jobs.find(j=>j.id===id);
    switch(action){
      case 'home':e.preventDefault();land();render();if(page==='pricing')updateCalc();break;
      case 'menu':$('.sidebar')?.classList.toggle('open');break;
      case 'toggle-theme':toggleTheme();break;
      case 'new-job':jobForm();break;
      case 'new-day-job':jobForm(null,{date:selectedDay});break;
      case 'slot-job':jobForm(null,{date:el.dataset.date,time:el.dataset.time});break;
      case 'day-slots':openDaySlots(selectedDay);break;
      case 'equal-shares':splitFormShares();break;
      case 'close-modal':closeModal();break;
      case 'help':helpModal();break;
      case 'profile':if(cloud){cloudProfile();break;}modal('Pracovné profily','Prepnúť pohľad v HTML ukážke.',`<div class="profile-options">${profileOptions()}</div><div class="help-box" style="margin-top:20px">Demo profily neoverujú heslo. Zákazky a výplaty sú uložené v tomto prehliadači.</div>`,`<button class="btn btn-secondary" data-action="logout">${icon('logout')}Odhlásiť profil</button>`,480);break;
      case 'logout':if(cloud){await cloudLogout();break;}setSession(null);break;
      case 'auth-login':authMode='login';cloudError='';renderCloudLogin();break;
      case 'auth-register':authMode='register';cloudError='';renderCloudLogin();break;
      case 'auth-reset':authMode='reset';cloudError='';renderCloudLogin();break;
      case 'cloud-refresh':await refreshCloud(true);break;
      case 'local-backup':localBackup();break;
      case 'notifications':{const upcoming=data.jobs.filter(j=>j.date>=today&&['planned','active'].includes(j.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,4);modal('Čo je pred nami','Najbližšie pracovné termíny.',upcoming.map(j=>`<div class="list-row"><div><b>${shortDate(j.date)} · ${j.time}</b><p>${esc(workText(j))} · Farma #${esc(j.farm)} · ${j.crew.length} osôb</p></div>${badge(j.status)}</div>`).join('')||'<div class="empty">Všetky zákazky sú hotové.</div>','',500);break;}
      case 'job-detail':jobDetail(id);break;
      case 'calendar-detail':jobDetail(id,!allowed('jobs'));break;
      case 'edit-job':if(j)jobForm(j);break;
      case 'start-job':await startJob(id);break;
      case 'complete-job':await finishJob(id);break;
      case 'cancel-job':if(gate('jobs')&&j)modal('Zrušiť rozpracovanú zákazku?','Stopky sa zastavia. Za zrušenú zákazku sa odmeny nepripočítajú.','<p class="text-muted" style="line-height:1.9">Doterajší nameraný čas zostane uložený pri zrušenej zákazke.</p>',`<button class="btn btn-secondary" data-action="job-detail" data-id="${id}">Pokračovať v práci</button><button class="btn btn-danger" data-action="confirm-cancel-job" data-id="${id}">Zrušiť zákazku</button>`,480);break;
      case 'confirm-cancel-job':await cancelJob(id);break;
      case 'delete-job':if(gate('jobs')&&j)modal('Odstrániť zákazku?',esc(j.id)+' · '+esc(j.first+' '+j.last),'<div id="form-error" class="hidden"></div><p style="color:var(--muted);font-size:12px;line-height:1.8">Odstráni sa zákazka aj jej podiel na zárobkoch. Zmenu nie je možné vrátiť. Ak chceš zachovať záznam, môžeš radšej zmeniť jej stav na zrušenú.</p>',`<button class="btn btn-secondary" data-action="close-modal">Ponechať</button><button class="btn btn-danger" data-action="confirm-delete-job" data-id="${id}">Odstrániť zákazku</button>`,470);break;
      case 'confirm-delete-job':if(cloud){if(gate('jobs')&&await cloudWrite('job_delete',{id}))toast('Zákazka bola odstránená.');break;}if(gate('jobs')&&applyJobChange(data.jobs.filter(x=>x.id!==id)))toast('Zákazka bola odstránená.');break;
      case 'quote-job':if(lastCalc)jobForm(null,{fields:lastCalc.fields,works:lastCalc.works,estimatedDurationSeconds:lastCalc.durationSeconds,price:lastCalc.price,crew:data.users.slice(0,Math.min(lastCalc.people,data.users.length)).map(u=>u.id)});break;
      case 'copy-quote':if(lastCalc){const c=lastCalc,text=`FarmCrew – ${c.work}\n${c.fields} políčok · ${c.people} pracovníci · ${durationText(c.durationSeconds)}\nOdporúčaná cena: ${number(c.price)} ${data.settings.currency}`;try{await navigator.clipboard.writeText(text);toast('Ponuka skopírovaná.');}catch{modal('Tvoja ponuka','Označ text a skopíruj ho.',`<textarea rows="5" readonly style="width:100%">${esc(text)}</textarea>`);}}break;
      case 'prev-month':case 'next-month':{const d=dateOf(calMonth+'-01');d.setMonth(d.getMonth()+(action==='next-month'?1:-1));calMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');selectedDay=calMonth+'-01';render();break;}
      case 'today':calMonth=today.slice(0,7);selectedDay=today;render();break;
      case 'new-user':employeeForm();break;
      case 'edit-user':employeeForm(data.users.find(u=>u.id===id));break;
      case 'new-payment':paymentForm();break;
      case 'pay-user':paymentForm(id);break;
      case 'export':exportJobs();break;
      case 'backup':if(isLeader()&&gate('settings')){download(JSON.stringify(data,null,2),`farmcrew-zaloha-${today}.json`,'application/json');toast('Záloha je pripravená na stiahnutie.');}break;
      case 'clear-demo':if(cloud)break;if(isLeader()&&gate('settings'))modal('Začať s čistým panelom?','Táto zmena odstráni všetky zákazky aj výplaty.',`<p style="font-size:12px;line-height:1.8;color:var(--muted)">Členovia, roly a nastavenia zostanú zachované. Pred vymazaním si môžeš stiahnuť kompletnú zálohu v nastaveniach.</p>`,`<button class="btn btn-secondary" data-action="close-modal">Ponechať dáta</button><button class="btn btn-danger" data-action="confirm-clear">Vymazať zákazky a výplaty</button>`,470);break;
      case 'confirm-clear':if(cloud)break;if(isLeader()&&gate('settings')){data.jobs=[];data.payments=[];save();closeModal();render();toast('Panel je pripravený na vaše vlastné zákazky.');}break;
    }return;
  }
  const day=e.target.closest('[data-day]');if(day){selectedDay=day.dataset.day;render();if(window.innerWidth<=1200)openDaySlots(selectedDay);return;}
  if(e.target.classList.contains('modal-overlay'))closeModal();
  if($('.sidebar.open')&&!e.target.closest('.sidebar')&&!e.target.closest('[data-action="menu"]'))$('.sidebar').classList.remove('open');
});
document.addEventListener('input',e=>{
  if(e.target.closest('#calc-form'))updateCalc();
  if(e.target.matches('[data-worker-share]')){const f=$('#job-form');if(f)f.dataset.customShares='yes';updateShareSummary();}
  if(e.target.id==='j-price')updateShareSummary();
  if(e.target.id==='job-search'){query=e.target.value;const filtered=data.jobs.filter(j=>(jobFilter==='all'||j.status===jobFilter)&&`${j.first} ${j.last} ${j.farm} ${j.id} ${workText(j)}`.toLocaleLowerCase('sk').includes(query.toLocaleLowerCase('sk'))).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time));$('#jobs-table').innerHTML=jobTable(filtered);$('#job-count').textContent=filtered.length+' z '+data.jobs.length+' zákaziek';$('#job-sum').innerHTML=money(filtered.filter(j=>j.status!=='cancelled').reduce((a,j)=>a+j.price,0));}
});
document.addEventListener('change',async e=>{
  if(e.target.id==='chart-days'){chartDays=+e.target.value;render();}
  if(e.target.id==='pay-filter'){payFilter=e.target.value;render();}
  if(e.target.matches('[name="crew"]')){const form=$('#job-form');if(form?.dataset.customShares==='no')splitFormShares();else updateShareSummary();}
  if(e.target.id==='p-user'){const amount=Math.floor(debt(e.target.value));$('#payment-balance').innerHTML='Čaká na vyplatenie: '+money(amount);$('#p-amount').max=amount;$('#p-amount').value=amount||'';}
  if(e.target.dataset.permission){if(!isLeader()||!gate('team')){render();return;}const r=e.target.dataset.permission;if(cloud){const perms=e.target.checked?[...new Set([...data.permissions.employee,r])]:data.permissions.employee.filter(p=>p!==r);if(await cloudWrite('permissions_save',{employee:perms}))toast('Oprávnenia sú uložené.');else render();return;}if(e.target.checked)data.permissions.employee=[...new Set([...data.permissions.employee,r])];else data.permissions.employee=data.permissions.employee.filter(p=>p!==r);save();toast('Oprávnenia zamestnancov boli uložené.');}
});
document.addEventListener('submit',async e=>{
  const f=e.target;e.preventDefault();if(!f.reportValidity())return;const fd=new FormData(f),v=Object.fromEntries(fd);
  if(f.id==='cloud-auth-form'){await submitCloudAuth(v);return;}
  if(cloud&&cloudBusy){formError('Počkaj na uloženie predošlej zmeny.');return;}
  if(f.id==='calc-form')return;
  if(f.id==='job-form'){
    if(!gate('jobs'))return;const crew=fd.getAll('crew'),works=workNames.filter(w=>fd.getAll('works').includes(w));
    if(!crew.length||new Set(crew).size!==crew.length||crew.some(id=>!data.users.some(u=>u.id===id))){formError('Priraď aspoň jedného platného pracovníka.');return;}
    if(!works.length){formError('Vyber aspoň jednu prácu.');return;}
    const existing=data.jobs.find(j=>j.id===f.dataset.id),workerShares=Object.fromEntries(crew.map(id=>{const value=Number(v['share-'+id]),old=existing&&workerPercent(existing,id);return [id,existing&&existing.crew.includes(id)&&value===Number(old.toFixed(6))?old:value];})),share=Object.values(workerShares).reduce((a,n)=>a+n,0);
    if(Object.values(workerShares).some(n=>!Number.isFinite(n)||n<0||n>100)||share>100+1e-9){formError('Podiel každého pracovníka musí byť 0–100 %. Súčet nesmie prekročiť 100 %.');return;}
    const fixedStatus=existing&&['active','completed'].includes(existing.status),status=fixedStatus?existing.status:v.status;
    if(!fixedStatus&&!['planned','cancelled'].includes(status)){formError('Zákazku spustíš tlačidlom „Začať zákazku“ a dokončíš tlačidlom „Dokončiť“.');return;}
    const measured=Number.isFinite(existing?.startedAt),durationSeconds=status==='completed'?(measured?storedJobSeconds(existing):durationFromValues(v)):status==='cancelled'&&existing?.status==='cancelled'?storedJobSeconds(existing):0;
    const optionalParts=['durationHours','durationMinutes','durationSecondsPart'],estimatedDurationSeconds=status==='completed'?(existing?.estimatedDurationSeconds||0):optionalParts.every(k=>v[k]===undefined||v[k]==='')?0:durationFromValues(v);
    const obj={...existing,id:existing?.id||'FC-'+data.nextJob,first:(v.first||'').trim(),last:(v.last||'').trim(),farm:v.farm,floor:(v.floor||'').trim(),fields:+v.fields,works,work:works.join(', '),crew,durationSeconds,minutes:durationSeconds/60,estimatedDurationSeconds,date:v.date,time:v.time,price:+v.price,status,note:(v.note||'').trim(),workerShares,share};
    if(status==='planned'){obj.startedAt=null;obj.completedAt=null;obj.stoppedAt=null;}
    if(!obj.first||!obj.last||!obj.floor||!farmNumbers.includes(obj.farm)||!fieldSizes.includes(obj.fields)||!timeSlots.includes(obj.time)||!Number.isInteger(durationSeconds)||durationSeconds<0||(status==='completed'&&durationSeconds<1)||!Number.isInteger(estimatedDurationSeconds)||estimatedDurationSeconds<0||estimatedDurationSeconds>359999||!Number.isFinite(obj.price)||obj.price<1||obj.price>1e9||!/^\d{4}-\d{2}-\d{2}$/.test(obj.date)||!Number.isFinite(Date.parse(obj.date))){formError('Skontroluj povinné údaje. Odhad trvania je nepovinný a musí mať platný formát hodiny : minúty : sekundy.');return;}
    const busy=data.jobs.find(j=>j.id!==obj.id&&hasRunningTimer(j)&&obj.status==='active'&&obj.crew.some(uid=>j.crew.includes(uid)));if(busy){formError('Pracovník už má spustenú zákazku '+busy.id+'.');return;}
    const start=Date.parse(obj.date+'T'+obj.time+':00Z'),end=start+scheduleSeconds(obj)*1000;
    const overlapping=data.jobs.find(j=>{const otherStart=Date.parse(j.date+'T'+j.time+':00Z');return j.id!==obj.id&&!['cancelled','completed'].includes(j.status)&&!['cancelled','completed'].includes(obj.status)&&obj.crew.some(id=>j.crew.includes(id))&&start<otherStart+scheduleSeconds(j)*1000&&otherStart<end;});
    if(overlapping){formError('Termín sa prekrýva so zákazkou '+overlapping.id+' pre aspoň jedného pracovníka. Vyber iný čas alebo partiu.');return;}
    if(cloud){const result=await cloudWrite('job_save',{...obj,id:existing?.id||null});if(result){jobDetail(result.changedId);toast('Zákazka je uložená v spoločnom paneli.');}return;}
    const list=existing?data.jobs.map(j=>j.id===obj.id?obj:j):[...data.jobs,obj];if(applyJobChange(list)){if(!existing){data.nextJob++;save();jobDetail(obj.id);}toast(existing?'Zákazka bola aktualizovaná.':'Zákazka je uložená. Keď začneš pracovať, klikni na „Začať zákazku“.');}return;
  }
  if(f.id==='cloud-member-form'){if(isLeader()&&await cloudWrite('member_save',{id:f.dataset.id||null,name:v.name,email:v.email,role:v.role,active:v.active==='true'}))toast('Člen partie je uložený.');return;}
  if(f.id==='user-form'){
    if(!isLeader()||!gate('team'))return;const name=v.name.trim();if(name.split(/\s+/).length<2){formError('Zadaj meno aj priezvisko člena.');return;}
    if(data.users.some(u=>u.id!==f.dataset.id&&u.name.toLocaleLowerCase()===name.toLocaleLowerCase())){formError('Člen s týmto menom už existuje.');return;}
    const existing=data.users.find(u=>u.id===f.dataset.id);if(existing?.role==='leader'&&v.role!=='leader'&&data.users.filter(u=>u.role==='leader').length===1){formError('Tím musí mať aspoň jedného leadera.');return;}
    if(existing)Object.assign(existing,{name,role:v.role});else data.users.push({id:'u'+Date.now(),name,role:v.role,color:['green','blue','purple'][data.users.length%3]});save();closeModal();render();toast('Profil člena bol uložený.');return;
  }
  if(f.id==='payment-form'){
    if(!isLeader()||!gate('payouts'))return;const amount=+v.amount;if(!data.users.some(u=>u.id===v.uid)||!Number.isFinite(amount)||amount<=0||amount>debt(v.uid)+.01){formError('Suma musí byť väčšia ako nula a nesmie prekročiť nevyplatený zárobok.');return;}if(v.date>today){formError('Odoslaná výplata nemôže mať budúci dátum.');return;}
    if(cloud){if(await cloudWrite('payment_add',{uid:v.uid,amount,date:v.date,note:v.note.trim()}))toast('Výplata je uložená.');return;}
    data.payments.push({id:'p'+Date.now(),uid:v.uid,amount,date:v.date,note:v.note.trim()});save();closeModal();render();toast('Výplata zapísaná. Zostatok člena bol aktualizovaný.');return;
  }
  if(f.id==='workspace-form'){if(!gate('settings'))return;if(!v.name.trim()||!v.server.trim()||!v.currency.trim())return;if(cloud){if(await cloudWrite('settings_save',{name:v.name.trim(),server:v.server.trim(),currency:v.currency.trim()}))toast('Údaje partie sú uložené.');return;}Object.assign(data.settings,{name:v.name.trim(),server:v.server.trim(),currency:v.currency.trim()});save();render();toast('Údaje pracovného priestoru boli uložené.');return;}
  if(f.id==='rates-form'){if(!gate('settings'))return;const fieldRate=+v.fieldRate,hourRate=+v.hourRate,share=+v.share;if(![fieldRate,hourRate,share].every(Number.isFinite)||fieldRate<1||hourRate<1||share<0||share>100)return;if(cloud){if(await cloudWrite('settings_save',{fieldRate,hourRate,share}))toast('Cenník je uložený.');return;}Object.assign(data.settings,{fieldRate,hourRate,share});save();render();toast('Sadzby a podiel pre nové zákazky boli uložené.');}
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){closeModal();$('.sidebar.open')?.classList.remove('open');}
  if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-day]')){e.preventDefault();e.target.click();}
  if(e.key==='Tab'&&$('.modal')){const focusable=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]',$('.modal')),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
window.addEventListener('storage',e=>{if(!cloud&&e.key===keys.data&&e.newValue){try{const incoming=JSON.parse(e.newValue);if([1,2,3].includes(incoming.version)){data=migrateData(incoming);render();if(page==='pricing')updateCalc();toast('Dáta boli obnovené zo zmeny v inom okne.');}}catch{}}});
if(cloud){bootCloud();}else{land();save();render();if(page==='pricing')updateCalc();}

